nppx.registerCommand("community.md.preview", () => {
  const raw = nppx.getActiveText();
  if (!raw.trim()) {
    nppx.notify("Nothing to preview");
    return;
  }
  nppx.openPreview({
    title: "Markdown — " + (nppx.getActiveFileName() || "untitled"),
    html: raw,
    mode: "markdown",
    allowScripts: true,
  });
});
nppx.registerCommand("community.md.previewClose", () => {
  nppx.closePreview();
});
